mapper.select:
SELECT PRJ_APLCNT_NO
FROM PRJ_APLCNT
WHERE USER_ID = #{userId}
  AND PRJ_ANNC_NO = #{prjAnncNo}

mapper.update:
UPDATE PRJ_APLCNT
SET
	APLCNT_STATUS_CODE = #{aplcntStatusCode}
WHERE PRJ_APLCNT_NO = #{prjAplcntNo}

mapper.insert:

    SELECT
        'PJAC'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(PRJ_APLCNT_NO), LENGTH('PJAC' ) + 1)), 0) + 1, 6, '0')
    FROM PRJ_APLCNT

INSERT INTO PRJ_APLCNT (
	PRJ_APLCNT_NO
	, RESUME_NO
	, USER_ID
	, APLCNT_STATUS_CODE
	, APLCNT_DATE
	, RCRT_PSNCNT_NO
	, PRJ_ANNC_NO
) VALUES (
	#{prjAplcntNo}
	, #{resumeNo}
	, #{userId}
	, #{aplcntStatusCode}
	, SYSDATE
	, #{rcrtPsncntNo}
	, #{prjAnncNo}
)
